        self.assertFalse(b.check_balanced_brackets())

    def test_check_balanced_brackets_3(self):
        b = BalancedBrackets("([)]")
        self.assertFalse(b.check_balanced_brackets())

    def test_check_balanced_brackets_4(self):
        b = BalancedBrackets("x{ y [z] } w")
